// HTTP bridge: exposes configured HTTP endpoints as plugin methods, one method per endpoint.
// Requests are built from templates (see config.ts); secret headers are read from files by path.
//
// Instance manifest example (plugins/http-github/plugin.json, generated by renderManifest):
//   "run": { "command": ["bun", "../../bridges/http/src/main.ts"] }
//   "permissions": ["network"], "provides": { "methods": ["issue.get"] }
// and in me.config.json / me.local.json:
//   "pluginConfig": { "http-github": { "baseUrl": "https://api.github.com",
//     "headers": { "authorization": { "file": "~/.config/me/secrets/github.token", "format": "Bearer {secret}" } },
//     "endpoints": { "issue.get": { "url": "/repos/{repo_owner}/{repo}/issues/{n}", "params": { ... }, "parse": "json" } } } }
import { definePlugin, type MethodHandler } from "@me/sdk";
import { validateConfig } from "./config.ts";
import { sendRequest } from "./request.ts";

// The SDK looks methods up at call time, so this object is filled once config arrives in initialize.
const methods: Record<string, MethodHandler> = {};

const plugin = definePlugin({
  methods,
  onInit(info) {
    const config = validateConfig(info.config);
    for (const [name, endpoint] of Object.entries(config.endpoints)) {
      methods[name] = (params, ctx) => sendRequest(name, config, endpoint, params, { signal: ctx.signal });
    }
  },
});

await plugin.run();
